local Player = {}
Player.__index = Player
function Player.new(name, score)
    assert(type(name) == "string" and name ~= "", "name required")
    return setmetatable({ name = name, score = score or 0 }, Player)
end
function Player:add_points(points) self.score = self.score + points end
local player = Player.new("Mina", 5)
player:add_points(3)
print(player.name, player.score)

